def solve(payload):
    import math
    layers = payload["layers"]
    if not layers or any(layer["thickness_m"] < 0 or layer["conductivity_w_mk"] <= 0 or layer["area_m2"] <= 0 for layer in layers):
        return {"error": "invalid_layers"}
    resistances = [layer["thickness_m"] / (layer["conductivity_w_mk"] * layer["area_m2"]) for layer in layers]
    total = math.fsum(resistances)
    if total <= 0:
        return {"error": "invalid_layers"}
    heat = (payload["hot_c"] - payload["cold_c"]) / total
    temperatures = [payload["hot_c"]]
    accumulated = 0.0
    for resistance in resistances:
        accumulated += resistance
        temperatures.append(payload["hot_c"] - heat * accumulated)
    return {"heat_flow_w": heat, "interface_temperatures_c": temperatures}
